\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Coastal Tide-Gauge Network\\Annual Data Report 2025}
\author{M.~Iversen and R.~Castellanos\\Harbour Hydrology Office\\\texttt{tideoffice@example.org}}
\date{January 2026}

\begin{document}
\maketitle

\begin{abstract}
The regional tide-gauge network recorded sea level at eleven stations
throughout 2025. This report describes the processing chain from raw
sensor output to the published hourly series, documents the quality
screening applied to every channel, and summarises the annual mean
sea-level and harmonic-constant products delivered to the Regional
Harbour Board. Two stations required major repairs after the February
storm; all other channels exceeded the 95\% availability target.
\end{abstract}

